INSERT INTO "tasks" VALUES('task_PvlJjQnCiHTjbs3Ptkj13','Industrial Sentinel External Deployment 15','Deploy Industrial Platform Autonomous Treasury & Payment Sentinel into a genuine external runtime that you or your operator already own or are explicitly authorized to manage.

Immutable container: ghcr.io/industrial-platform-ai/industrial-sentinel-runtime@sha256:c47e8282b0dd43aa9d46d22ce8814e1cb52bb85499275e3695d53ac4d7c537f4

